-- Phase 49: operational document compliance. Legal interpretation and signing are out of scope.
alter table public.plans add column if not exists document_compliance_enabled boolean not null default true;
alter table public.plans add column if not exists contract_management_enabled boolean not null default true;
alter table public.plans add column if not exists license_tracking_enabled boolean not null default true;
alter table public.plans add column if not exists renewal_workflows_enabled boolean not null default true;
alter table public.plans add column if not exists document_ai_assistant_enabled boolean not null default true;

create table public.compliance_document_categories(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,name text not null,active boolean not null default true,created_at timestamptz not null default now(),unique(organization_id,name));
create table public.compliance_documents(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,store_id uuid references public.establishments(id) on delete restrict,category_id uuid references public.compliance_document_categories(id) on delete set null,document_type text not null,title text not null,description text,owner_user_id uuid references auth.users(id) on delete set null,backup_owner_user_id uuid references auth.users(id) on delete set null,related_entity_type text,related_entity_id uuid,status text not null default 'draft' check(status in('draft','active','expiring_soon','expired','under_review','renewal_in_progress','terminated','archived')),issue_date date,effective_from date,expiration_at timestamptz,renewal_required boolean not null default false,renewal_lead_days integer check(renewal_lead_days is null or renewal_lead_days>=0),issuer text,document_number text,confidentiality_level text not null default 'normal' check(confidentiality_level in('normal','restricted','confidential')),current_version_id uuid,criticality text not null default 'normal' check(criticality in('low','normal','high','critical')),retention_until date,legal_hold_future boolean not null default false,created_by uuid references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.compliance_document_versions(id uuid primary key default gen_random_uuid(),document_id uuid not null references public.compliance_documents(id) on delete restrict,version_number integer not null check(version_number>0),file_id uuid not null references public.internal_attachments(id) on delete restrict,uploaded_by uuid references auth.users(id) on delete set null,uploaded_at timestamptz not null default now(),effective_from date,notes text,checksum_sha256 text not null check(length(checksum_sha256)=64),status text not null default 'draft' check(status in('current','superseded','draft','invalidated')),malware_scan_status text not null default 'pending' check(malware_scan_status in('pending','clean','blocked','failed')),metadata_extraction_status text not null default 'pending' check(metadata_extraction_status in('pending','suggested','confirmed','rejected','failed')),unique(document_id,version_number),unique(document_id,checksum_sha256));
alter table public.compliance_documents add constraint compliance_documents_current_version_fk foreign key(current_version_id) references public.compliance_document_versions(id) on delete set null;
create table public.compliance_document_acl(id uuid primary key default gen_random_uuid(),document_id uuid not null references public.compliance_documents(id) on delete cascade,scope_type text not null check(scope_type in('organization','region','store','role','user')),scope_id text not null,permission text not null check(permission in('view','download','manage','approve','view_contract_value')),created_by uuid references auth.users(id),created_at timestamptz not null default now(),unique(document_id,scope_type,scope_id,permission));
create table public.contracts(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,store_id uuid references public.establishments(id) on delete restrict,document_id uuid not null unique references public.compliance_documents(id) on delete restrict,counterparty_type text not null check(counterparty_type in('supplier','landlord','service_provider','partner','other')),counterparty_id uuid,responsible_user_id uuid references auth.users(id) on delete set null,contract_category text,start_at date not null,end_at date,auto_renew boolean not null default false,notice_period_days integer check(notice_period_days is null or notice_period_days>=0),contract_value_cents bigint,billing_frequency text,status text not null default 'draft' check(status in('draft','review','approved','active','expiring','renewal_review','renewed','terminated','expired')),approval_id uuid references public.internal_approvals(id) on delete set null,financial_commitment_id uuid references public.financial_entries(id) on delete set null,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.licenses_and_permits(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,store_id uuid references public.establishments(id) on delete restrict,document_id uuid not null unique references public.compliance_documents(id) on delete restrict,authority_name text,license_type text not null,issue_date date,expiration_at timestamptz,status text not null default 'active',renewal_required boolean not null default false,responsible_user_id uuid references auth.users(id) on delete set null,created_at timestamptz not null default now());
create table public.certificates(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,store_id uuid references public.establishments(id) on delete restrict,document_id uuid not null unique references public.compliance_documents(id) on delete restrict,certificate_type text not null,related_entity_type text,related_entity_id uuid,issued_by text,issued_at date,expiration_at timestamptz,status text not null default 'active',created_at timestamptz not null default now());
create table public.insurance_policies(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,store_id uuid references public.establishments(id) on delete restrict,document_id uuid not null unique references public.compliance_documents(id) on delete restrict,provider_name text not null,policy_number text,coverage_type text not null,insured_entity_type text not null,insured_entity_id uuid,start_at date not null,end_at date not null,premium_value_cents bigint,status text not null default 'active',contact_info jsonb,created_at timestamptz not null default now());
create table public.operational_obligations(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,store_id uuid references public.establishments(id) on delete restrict,title text not null,category text not null,description text,recurrence text not null,due_rule jsonb not null default '{}',responsible_user_id uuid references auth.users(id) on delete set null,backup_owner_user_id uuid references auth.users(id) on delete set null,status text not null default 'active' check(status in('active','paused','completed','archived')),related_document_type text,evidence_required boolean not null default false,active boolean not null default true,source text not null default 'manual' check(source in('manual','organization_template','ai_suggestion_confirmed')),created_by uuid references auth.users(id),created_at timestamptz not null default now());
create table public.obligation_occurrences(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,store_id uuid references public.establishments(id) on delete restrict,obligation_id uuid not null references public.operational_obligations(id) on delete restrict,due_at timestamptz not null,status text not null default 'upcoming' check(status in('upcoming','due','overdue','completed','waived','not_applicable')),completed_at timestamptz,completed_by uuid references auth.users(id) on delete set null,evidence_document_id uuid references public.compliance_documents(id) on delete set null,notes text,waiver_reason text,waived_by uuid references auth.users(id) on delete set null,created_at timestamptz not null default now(),check(status not in('waived','not_applicable') or waiver_reason is not null));
create table public.document_reminder_settings(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,document_id uuid references public.compliance_documents(id) on delete cascade,document_type text,alert_windows_days integer[] not null default '{90,60,30,15,7,1}',channels text[] not null default '{in_app}',cooldown_hours integer not null default 24 check(cooldown_hours between 1 and 720),daily_digest boolean not null default false,active boolean not null default true,created_at timestamptz not null default now(),check(document_id is not null or document_type is not null));
create table public.document_alerts(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,store_id uuid references public.establishments(id) on delete cascade,document_id uuid references public.compliance_documents(id) on delete cascade,obligation_occurrence_id uuid references public.obligation_occurrences(id) on delete cascade,alert_type text not null check(alert_type in('upcoming_expiration','notice_deadline','missing_document','overdue_obligation','renewal_pending','approval_pending')),severity text not null,dedup_key text not null,status text not null default 'open' check(status in('open','acknowledged','resolved')),recipient_user_id uuid references auth.users(id) on delete set null,evidence jsonb not null default '{}',last_sent_at timestamptz,created_at timestamptz not null default now(),resolved_at timestamptz,unique(organization_id,dedup_key,status));
create table public.document_renewals(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,document_id uuid not null references public.compliance_documents(id) on delete restrict,status text not null default 'not_started' check(status in('not_started','gathering_documents','submitted','awaiting_response','approved','rejected','completed','cancelled')),started_at timestamptz,target_completion_at timestamptz,owner_user_id uuid references auth.users(id) on delete set null,provider_id uuid references public.suppliers(id) on delete set null,checklist_id uuid references public.network_operational_standards(id) on delete set null,new_document_id uuid references public.compliance_documents(id) on delete set null,approval_id uuid references public.internal_approvals(id) on delete set null,notes text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.document_relationships(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,source_document_id uuid not null references public.compliance_documents(id) on delete restrict,target_document_id uuid not null references public.compliance_documents(id) on delete restrict,relationship_type text not null check(relationship_type in('renews','replaces','supports','references','evidence_for')),created_by uuid references auth.users(id),created_at timestamptz not null default now(),unique(source_document_id,target_document_id,relationship_type),check(source_document_id<>target_document_id));
create table public.required_document_templates(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,scope_type text not null check(scope_type in('organization','region','cluster','store','supplier','asset')),scope_id uuid,document_type text not null,title text not null,required boolean not null default true,expiration_expected boolean not null default false,evidence_required boolean not null default true,confidentiality_level text not null default 'normal',active boolean not null default true,created_by uuid references auth.users(id),created_at timestamptz not null default now());
create table public.document_ai_suggestions(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,document_id uuid not null references public.compliance_documents(id) on delete cascade,version_id uuid not null references public.compliance_document_versions(id) on delete cascade,suggestion_type text not null check(suggestion_type in('classification','metadata','clause_summary','obligation')),suggested_data jsonb not null,provenance jsonb not null default '{}',status text not null default 'suggested' check(status in('suggested','confirmed','rejected')),confirmed_by uuid references auth.users(id) on delete set null,confirmed_at timestamptz,created_at timestamptz not null default now());
create table public.document_download_audit(id bigint generated always as identity primary key,organization_id uuid not null references public.organizations(id) on delete cascade,document_id uuid not null references public.compliance_documents(id) on delete restrict,version_id uuid references public.compliance_document_versions(id) on delete set null,actor_user_id uuid references auth.users(id) on delete set null,confidentiality_level text not null,access_reason text,signed_url_ttl_seconds integer,created_at timestamptz not null default now());
create table public.document_audit_events(id bigint generated always as identity primary key,organization_id uuid not null references public.organizations(id) on delete cascade,store_id uuid references public.establishments(id) on delete set null,actor_user_id uuid references auth.users(id) on delete set null,event_type text not null,entity_type text not null,entity_id uuid,reason text,before_state jsonb,after_state jsonb,metadata jsonb not null default '{}',created_at timestamptz not null default now());
create table public.fact_contracts(id uuid primary key default gen_random_uuid(),organization_id uuid not null,store_id uuid,contract_id uuid,status text,contract_value_cents bigint,start_at date,end_at date,loaded_at timestamptz not null default now());
create table public.fact_document_expirations(id uuid primary key default gen_random_uuid(),organization_id uuid not null,store_id uuid,document_id uuid,document_type text,status text,expiration_at timestamptz,loaded_at timestamptz not null default now());
create table public.fact_obligations(id uuid primary key default gen_random_uuid(),organization_id uuid not null,store_id uuid,occurrence_id uuid,status text,due_at timestamptz,completed_at timestamptz,loaded_at timestamptz not null default now());
create table public.fact_document_renewals(id uuid primary key default gen_random_uuid(),organization_id uuid not null,document_id uuid,status text,cycle_time_hours numeric,loaded_at timestamptz not null default now());
create table public.fact_document_approvals(id uuid primary key default gen_random_uuid(),organization_id uuid not null,document_id uuid,approval_id uuid,status text,decision_time_hours numeric,loaded_at timestamptz not null default now());
create table public.dim_document_type(document_type text primary key,label text not null);
create table public.dim_contract_category(category text primary key,label text not null);
create table public.dim_obligation_category(category text primary key,label text not null);

create index compliance_docs_expiry_idx on public.compliance_documents(organization_id,expiration_at,status);
create index compliance_docs_store_type_idx on public.compliance_documents(store_id,document_type,status);
create index compliance_docs_search_idx on public.compliance_documents(organization_id,title,document_number);
create index document_versions_doc_idx on public.compliance_document_versions(document_id,version_number desc);
create index contracts_notice_idx on public.contracts(organization_id,end_at,notice_period_days,status);
create index obligation_occurrence_due_idx on public.obligation_occurrences(organization_id,due_at,status);
create index renewals_status_idx on public.document_renewals(organization_id,status,target_completion_at);
create index document_audit_entity_idx on public.document_audit_events(entity_type,entity_id,created_at desc);

do $$ declare t text; begin foreach t in array array['compliance_document_categories','compliance_documents','compliance_document_versions','compliance_document_acl','contracts','licenses_and_permits','certificates','insurance_policies','operational_obligations','obligation_occurrences','document_reminder_settings','document_alerts','document_renewals','document_relationships','required_document_templates','document_ai_suggestions','document_download_audit','document_audit_events','fact_contracts','fact_document_expirations','fact_obligations','fact_document_renewals','fact_document_approvals','dim_document_type','dim_contract_category','dim_obligation_category'] loop execute format('alter table public.%I enable row level security',t);execute format('create policy %I on public.%I for all to service_role using(true) with check(true)',t||'_service_only',t);execute format('revoke all on public.%I from public,anon,authenticated',t);execute format('grant all on public.%I to service_role',t);end loop;end $$;
insert into public.dim_document_type values('contract','Contrato'),('license','Licença'),('permit','Alvará'),('insurance_policy','Seguro'),('certificate','Certificado'),('supplier_document','Documento de fornecedor'),('asset_document','Documento de ativo'),('lease','Locação'),('maintenance_agreement','Manutenção'),('service_agreement','Serviço'),('operational_policy','Política operacional'),('other','Outro') on conflict do nothing;
